import{_ as e,c as r,o,ah as t}from"./chunks/framework.Ch_PcVtW.js";const b=JSON.parse('{"title":"PART1","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/tmp_style_guide_input.md","filePath":"scripts/output/tmp_style_guide_input.md"}'),i={name:"scripts/output/tmp_style_guide_input.md"};function p(l,a,h,n,s,S){return o(),r("div",null,[...a[0]||(a[0]=[t('<p>你现在是顶级图书总编辑兼资深日语翻译专家。目前我们即将开始一个由多篇文章组成的翻译出版项目。 项目背景：这是一本由日经出版社和bmsg会社合作的连载文集，名为日高光启的管理学，以第一人称的短篇记录形式，结合第三人称的客观介绍，主要跟踪采访了bmsg公司的动向，和日高光启作为ceo和唱跳团体制作人的思考和评价，以及他本人的个人活动，和对行业的一些观点。日高光启本人作为rapper思维活跃，并接受过良好教育，待人平等和蔼，所以本文中语气既有作为专业管理者的一丝不苟和客观严谨，又有作为艺术家和艺术工作者的通情达理、充满激情和想象力。日经出版社作为常年观察bmsg公司动向的出版社，和日高的合作紧密。本书中涉及很多音乐专业和行业特有词汇，如果遇到英文可以保持英文并在括号中注释为常用中文。</p><p>为了确保整本书（所有章节）的人名、黑话、组合习惯用语、专有名词和文风语气达到100%的一致性，请你通读以下全部原文的采样切片，进行“全局术语与风格提取”。</p><h2 id="【需要你分析的日文原文切片合集】" tabindex="-1">【需要你分析的日文原文切片合集】： <a class="header-anchor" href="#【需要你分析的日文原文切片合集】" aria-label="Permalink to &quot;【需要你分析的日文原文切片合集】：&quot;">​</a></h2><p>=== 文件名: PART0/はじめに.md === はじめに</p><p>大層なサブタイトルに引かれてくださった方には拍子抜けかもしれませんが、実際のところ世界と日本の音楽業界に「壁」なんてものは、現在は存在しないのですよね。その前提だけお伝えできればこの前書きは役目を果たしているのですが、もう少し詳しく話しましょう。まずはそのために自己紹介をさせてください。</p><p>初めましての方は初めまして、そうでない方はいつもありがとうございます株式会社BMSG代表取締役CEOの日高と申します。またSKY-HIと言う名前で10代の頃からラッパーとしてキャリアを積んだり、2021年からはBE:FIRSTをはじめとしたボーイズグループのプロデューサーなどもしています。3つの肩書きを同時進行する毎日は、刺激的と言うか不安と幸福が縄の如くの日々です。奇特な人生ですね。</p><p>他に日高光啓と言う名前でAAAというグループを20年ほどやっていたり(現在活動休止中)、もっと遡れば中学生の頃から芸能活動をしていましたが、この期間、</p><ul><li>国内最大手事務所のアイドルの練習生</li><li>バンドマン</li><li>別の大手事務所の練習生</li><li>AAA</li><li>アンダーグラウンドのラッパー</li><li>インディーズレーベルのヘッド</li><li>BMSG起業</li><li></li></ul><p>=== 文件名: PART0/目次.md ===</p><p>はじめに</p><h2 id="part1-sky-hi-special-talk" tabindex="-1">PART1: SKY-HI Special Talk <a class="header-anchor" href="#part1-sky-hi-special-talk" aria-label="Permalink to &quot;PART1: SKY-HI Special Talk&quot;">​</a></h2><ul><li>急成長を続ける5年目のBMSG 「社会を善くする」ためのマネジメント</li></ul><h2 id="part2-2023年のbmsg" tabindex="-1">PART2: 2023年のBMSG <a class="header-anchor" href="#part2-2023年のbmsg" aria-label="Permalink to &quot;PART2: 2023年のBMSG&quot;">​</a></h2><ul><li>BE:FIRSTに続くグループMAZZELに込めた「迷路」と「情熱」</li><li>ビジネス系メディアの取材を通じて感じた自信と確信</li><li>BE:FIRST紅白歌合戦出場の意味とAAA時代に感じたこと</li><li>MAZZELを追うドキュメンタリー、エンタテインしない理由</li><li>2つ目のボーイズグループ「MAZZEL」を今作る理由</li><li>「好き=好き」を実現する身体性のために</li><li>BE:FIRSTに課す「大きな夢」のためのマイルストーン</li><li>BMSGを支えるB-Town、その重要性とリニューアルの狙い</li><li>SKY-HIが語るMAZZEL新たなオーディションで目指したもの</li><li>“BMSGに共鳴する仲間”を巻き込むパーティー開催</li><li>BE:FIRSTとMAZZELのリリースを振り返る</li><li>音楽番組『D.U.N.K.』をYouTubeでやる重要性</li><li>ソロのステージで「自分自身」を再定義したかった</li><li>ツアー初日前夜「久しぶりに眠れなかった」理由</li></ul><p>=== 文件名: PART1/0.md ===</p><h1 id="part1" tabindex="-1">PART1 <a class="header-anchor" href="#part1" aria-label="Permalink to &quot;PART1&quot;">​</a></h1><p>SKY-HI Special Talk</p><p><strong>急成長を続ける5年目のBMSG</strong><br><strong>「社会を善くする」ためのマネジメント</strong></p><p>=== 文件名: PART1/1.md ===</p><blockquote><p>2020年9月に設立されたBMSG。その社名は、「Be MySelf Group」が由来だ。誰もがありのままの自分で生きていくことを第1に、SKY-HIは小さな旗を掲げた。設立時、社員はSKY-HIたった1人、アーティストはSKY-HIとラッパーのNovel Coreのみ。法人登記はしているものの会社としてのリアルな「場」はなく、最初の頃、様々な郵便物の宛先はSKY-HIの実家だった。</p><p>それから4年後の今、BMSGはダンススタジオやレコーディングブース、さらにはサウナまでを備えた自社ビルを構え、社員数は約80人にまで増えた。所属アーティストは20人、さらにデビューを目指すトレーニー(練習生)たちを抱え、日本の芸能事務所としては決して小さくない規模となっている。</p><p>だが、BMSGを高く評価すべき点は、何よりもその活動のエンタテインメント業界に対する影響力、インパクトだろう。まずは改めてこの4年を振り返りながら、BMSGが何を大事にし、どこへ向かおうとしているのかを明らかにする。</p><p>21年のオーディション「THE FIRST」には、既存の音楽業界の枠組みにはまらず、輝ける場所がない夢を諦めざるを得ない、しかし才能</p></blockquote><p>=== 文件名: PART2/0.md ===</p><h2 id="part-2" tabindex="-1">PART 2 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;PART 2&quot;">​</a></h2><p>2023年のBMSG</p><p>01/13 MAZZEL 結成までを追うドキュメンタリー番組「MISSIONx2」が BMSG YouTube チャンネルでスタート</p><p>02/01 「D.U.N.K. -DANCE UNIVERSE NEVER KILLED-」の放送がスタート</p><p>02/24 BE:FIRST が初のワンマンツアー 「BE:FIRST 1st One Man Tour “BE:1&quot; 2022-2023」 を完走</p><p>03/01 ファンコミュニティ 「B-Town」 をオンラインサロンとしてリニューアルオープン</p><p>03/05 ライブイベント「D.U.N.K. Showcase」 を初めて有明アリーナで開催。 11日、12日には幕張メッセ公演も</p><p>03/22 edhiii boi が 1st アルバム 『edhiii boi is here』 をリリース</p><p>04/04 BMSGが関係者を招いたパーティ 「Greeting &amp; Gathering」 を初めて開催</p><p>05/13 「D.U.N.K.」 の YouTube 音楽番組がスタート</p><p>=== 文件名: PART2/1.md === ► 2022/11</p><h2 id="be-firstに続くグループmazzelに込めた「迷路」と「情熱」" tabindex="-1">BE:FIRSTに続くグループMAZZELに込めた「迷路」と「情熱」 <a class="header-anchor" href="#be-firstに続くグループmazzelに込めた「迷路」と「情熱」" aria-label="Permalink to &quot;BE:FIRSTに続くグループMAZZELに込めた「迷路」と「情熱」&quot;">​</a></h2><p>#新プロジェクト #Mx2 #MAZZEL #不安 #悩み #覚悟 #幸せ #オウンドメディア</p><h3 id="「生きているなかで不安や悩みといったものは常につきまとう。誰もが幸福になりたいはずだし、エンタテインメントはそういった気持ちの助けや啓蒙になるべきもの」" tabindex="-1">「生きているなかで不安や悩みといったものは常につきまとう。誰もが幸福になりたいはずだし、エンタテインメントはそういった気持ちの助けや啓蒙になるべきもの」 <a class="header-anchor" href="#「生きているなかで不安や悩みといったものは常につきまとう。誰もが幸福になりたいはずだし、エンタテインメントはそういった気持ちの助けや啓蒙になるべきもの」" aria-label="Permalink to &quot;「生きているなかで不安や悩みといったものは常につきまとう。誰もが幸福になりたいはずだし、エンタテインメントはそういった気持ちの助けや啓蒙になるべきもの」&quot;">​</a></h3><p><strong>2022年11月22日、BMSGは記者会見で、BMSGとユニバーサルミュージックとの合同レーベル「BE-U」の設立と、BE:FIRSTの次に放つ2つめのダンス&amp;ボーカルグループを電撃発表した。その名前は「MAZZEL(マーゼル)」。8人組のボーイズグループだ。今、彼らを世に発表した意図は?また、どんなグループになるのだろうか。</strong></p><p>「マーゼル」そのものには「福音」「幸運」の意味を持つ「mazel」の意味がありますが、さらに「Maze」(迷路)と「Zeal」(情熱など)の組み合わせです。人生というものは、彼らがデビュー前に経験した通り、悩んだり迷ったりする「迷路」みたいなもの。けれども、必ず「出口」はある。その「出口」に向けて情熱を燃やし、「幸福」をつかみとって人々に渡</p><p>=== 文件名: PART2/10.md === ► 2023/04</p><h2 id="bmsgに共鳴する仲間-を巻き込むパーティー開催" tabindex="-1">&quot;BMSGに共鳴する仲間”を巻き込むパーティー開催 <a class="header-anchor" href="#bmsgに共鳴する仲間-を巻き込むパーティー開催" aria-label="Permalink to &quot;&quot;BMSGに共鳴する仲間”を巻き込むパーティー開催&quot;">​</a></h2><p>#G&amp;G #関係性構築 #仲間づくり</p><h3 id="「正しく夢を見て、それに向かって正しく努力して、正しく仲間を増やして、正しくそれを成していくっていうことをビジネス的にも人生的にも推奨したい」" tabindex="-1">「正しく夢を見て、それに向かって正しく努力して、正しく仲間を増やして、正しくそれを成していくっていうことをビジネス的にも人生的にも推奨したい」 <a class="header-anchor" href="#「正しく夢を見て、それに向かって正しく努力して、正しく仲間を増やして、正しくそれを成していくっていうことをビジネス的にも人生的にも推奨したい」" aria-label="Permalink to &quot;「正しく夢を見て、それに向かって正しく努力して、正しく仲間を増やして、正しくそれを成していくっていうことをビジネス的にも人生的にも推奨したい」&quot;">​</a></h3><p><strong>4月上旬、BMSGは関係者を招いたパーティー「Greeting&amp;Gathering」(以下、「G&amp;G」)を開催した。3期目半ばに差し掛かったタイミングで、関係各社に感謝とあいさつを伝えることを目的としたものだった。こうしたパーティーの開催自体は珍しいものではないが、「G&amp;G」の場合は会場の演出からBMSGのアーティストやスタッフのホスピタリティーまで、全てにおいてBMSGのカラーに彩られていた。ベースはビジネスの関係でありながら、何よりも「すごく楽しい」ムードにあふれた空間だった。SKY-HIは、なぜこのパーティーを開催したのか。そして、なぜ「すごく楽しい」空間が可能だったのか。</strong></p><p>BMSGの設立から2年半がたち、おかげさまでBE:FIRSTや自分たちソロアーティストを応援してくれる方々やBMSGに共鳴してくれる方々が、音楽やメディア関係に限らず、各所</p><p>=== 文件名: PART2/11.md === ► 2023/05</p><h2 id="be-firstとmazzelのリリースを振り返る" tabindex="-1">BE:FIRSTとMAZZELのリリースを振り返る <a class="header-anchor" href="#be-firstとmazzelのリリースを振り返る" aria-label="Permalink to &quot;BE:FIRSTとMAZZELのリリースを振り返る&quot;">​</a></h2><p>#BEFIRST #MAZZEL #いい空気感</p><h3 id="「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」" tabindex="-1">「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」 <a class="header-anchor" href="#「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」" aria-label="Permalink to &quot;「自身がわくわくし続けてくれると、おのずとわくわくした空気感が周囲に漂うし、人はそうした空気感に引きつけられると思う」&quot;">​</a></h3><p>**2023年春、BMSGの2つのボーイズグループが大きく動いた。1つは4月26日のBE:FIRSTの3rdシングル『Smile Again』のリリース、もう1つは5月17日、BE:FIRSTに次ぐ新たなグループMAZZEL(マーゼル)のデビューである。BE:FIRST『Smile Again』は、資生堂の「ANESSA Global Campaign Song」として大型タイアップもついた、自身初のラブソング。5月3日公開の Billboard JAPAN ダウンロード・ソング・チャート&quot;Download Songs&quot;で初登場1位を果たしたが、結果的にはBE:FIRSTが初めて Billboard JAPAN で総合ソング・チャート“JAPAN Hot 100”で1位を取れなかった曲となった。それを阻んだのはYOASOBIの『アイドル』。4月12日の配信開始以来、5月20日現在、</p><p>=== 文件名: PART2/12.md === ► 2023/05</p><h2 id="音楽番組『d-u-n-k-』をyoutubeでやる重要性" tabindex="-1">音楽番組『D.U.N.K.』をYouTubeでやる重要性 <a class="header-anchor" href="#音楽番組『d-u-n-k-』をyoutubeでやる重要性" aria-label="Permalink to &quot;音楽番組『D.U.N.K.』をYouTubeでやる重要性&quot;">​</a></h2><p>#新プロジェクト #D.U.N.K. #発信 #YouTube #仲がいい #空気がいい</p><h3 id="「みんなが苦しみながら耐えている映像より、仲良く楽しくの空気感のコンテンツが伸びていく時代が来ている」" tabindex="-1">「みんなが苦しみながら耐えている映像より、仲良く楽しくの空気感のコンテンツが伸びていく時代が来ている」 <a class="header-anchor" href="#「みんなが苦しみながら耐えている映像より、仲良く楽しくの空気感のコンテンツが伸びていく時代が来ている」" aria-label="Permalink to &quot;「みんなが苦しみながら耐えている映像より、仲良く楽しくの空気感のコンテンツが伸びていく時代が来ている」&quot;">​</a></h3><p><strong>2023年に始まったダンス&amp;ボーカルの大型プロジェクト「D.U.N.K. -DANCE UNIVERSE NEVER KILLED-」。2月から日本テレビ系で同名番組がスタートし、3月には3日間にわたり「D.U.N.K. Showcase」を開催、SKY-HIやBE:FIRSTらBMSG所属アーティストに加え、DREAMS COME TRUE、GENERATIONS、&amp;TEAMら豪華アーティストが出演した。そして5月13日から新たな音楽番組がYouTubeで始まった。</strong></p><p><strong>「D.U.N.K. Showcase」で撮影されたオンステージカメラやドローンも使った迫力あるパフォーマンス映像に加え、ステージ裏の様子やつながりも見える番組は、スタジオでパフォーマンスする従来の音楽番組とは一線を画すものだ。</strong></p><p>**これまでもSKY-HI</p><p>=== 文件名: PART2/13.md === ► 2023/06</p><h2 id="ソロのステージで「自分自身」を再定義したかった" tabindex="-1">ソロのステージで「自分自身」を再定義したかった <a class="header-anchor" href="#ソロのステージで「自分自身」を再定義したかった" aria-label="Permalink to &quot;ソロのステージで「自分自身」を再定義したかった&quot;">​</a></h2><p>#自分の再定義 #肩書き #CEO #BOSS #SKY-HI</p><h3 id="「雑なカテゴライズや安易なラベリング、それによる偏見や逆偏見は昔から忌避している」" tabindex="-1">「雑なカテゴライズや安易なラベリング、それによる偏見や逆偏見は昔から忌避している」 <a class="header-anchor" href="#「雑なカテゴライズや安易なラベリング、それによる偏見や逆偏見は昔から忌避している」" aria-label="Permalink to &quot;「雑なカテゴライズや安易なラベリング、それによる偏見や逆偏見は昔から忌避している」&quot;">​</a></h3><p><strong>SKY-HIは自身のソロ活動史上最大のツアー『SKY-HI ARENA TOUR 2023 -BOSSDOM- 』を開催。5月に東京・代々木第一体育館、6月に大阪・大阪城ホールを各2公演ずつ巡った。長年活動を共にしてきたハウスバンドであるTHE SUPER FLYERS、ダンサーチームBFQに加え、今回はダンサーも4人追加。最新のライブ演出技術が空間を彩り、そこにエネルギーあふれるSKY-HIの圧巻のパフォーマンス。エンタテインメントの極致ともいうべき音楽の素晴らしさと強いメッセージが融合したすごみのあるパワーを感じさせた。</strong></p><p><strong>ライブ中のMCでは「BMSGは、あなたたちと一緒に時代を変える」という宣言もあり、ツアー名に冠した「BOSSDOM」という言葉とも相まって、これまでのSKY-HIのソロライブ以上にBMSGを率いる立場を感じる瞬間もあった。</strong></p><p>そうですね、前提としては「舐</p><p>=== 文件名: PART2/14.md === ► 2023/06</p><h2 id="ツアー初日前夜「久しぶりに眠れなかった」理由" tabindex="-1">ツアー初日前夜「久しぶりに眠れなかった」理由 <a class="header-anchor" href="#ツアー初日前夜「久しぶりに眠れなかった」理由" aria-label="Permalink to &quot;ツアー初日前夜「久しぶりに眠れなかった」理由&quot;">​</a></h2><p>#責任感 #プレッシャー #体制の向上 #感謝 #SKYHI</p><h3 id="「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」" tabindex="-1">「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」 <a class="header-anchor" href="#「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」" aria-label="Permalink to &quot;「期待をいただいたりしてしまうと、背負うものの重さを強く感じてどんどんプレッシャーになっていくんですが、それがパフォーマンスに良い影響を与えてくれている」&quot;">​</a></h3><p><strong>2023年6月18日、SKY-HIは東京・大阪の4公演で約4万人を動員した、自身史上最大のツアー『SKY-HI ARENA TOUR 2023 -BOSSDOM-』を終えた。今回は、「久々にライブ初日前に眠れなかった」というSKY-HIの話を紹介する。インタビューは東京公演と大阪公演の間に行った。</strong></p><p>「BOSSDOM」では、久しぶりに初日前に眠れなかったんですよね。りょんりょん(ボイストレーナーの佐藤涼子氏)にその話をしたら、「初日の前で熟睡できるアーティストなんていないわよ」って言われたけど。(笑)</p><p>たぶん緊張していたんでしょうね。初日が映像の収録ということもなかなかないし、それにもかかわらず当日やってみないと分かんない」っていうこともいっぱいあったし、立場や責任、タイミングも含めて「外しちゃいけない」感はすごくあ</p><p>=== 文件名: PART2/15.md === ► 2023/07</p><h2 id="新曲-ドキュメント映画で示すbe-firstの新境地" tabindex="-1">新曲&amp;ドキュメント映画で示すBE:FIRSTの新境地 <a class="header-anchor" href="#新曲-ドキュメント映画で示すbe-firstの新境地" aria-label="Permalink to &quot;新曲&amp;ドキュメント映画で示すBE:FIRSTの新境地&quot;">​</a></h2><p>#BEFIRST #グローバル #世界へ #範馬刃牙 #CJENM</p><h3 id="「-アニメのタイアップ曲-大ヒット-世界へ-という考えは短絡的。それよりも自分たちのストーリー、自分たちの楽曲として提示できるものを作らなきゃいけない」" tabindex="-1">「“アニメのタイアップ曲=大ヒット=世界へ”という考えは短絡的。それよりも自分たちのストーリー、自分たちの楽曲として提示できるものを作らなきゃいけない」 <a class="header-anchor" href="#「-アニメのタイアップ曲-大ヒット-世界へ-という考えは短絡的。それよりも自分たちのストーリー、自分たちの楽曲として提示できるものを作らなきゃいけない」" aria-label="Permalink to &quot;「“アニメのタイアップ曲=大ヒット=世界へ”という考えは短絡的。それよりも自分たちのストーリー、自分たちの楽曲として提示できるものを作らなきゃいけない」&quot;">​</a></h3><p><strong>この夏、BE:FIRSTが大きな動きを見せる。2023年8月25日に初ライブドキュメンタリー映画『BE：theONE』が全国公開、30日にはアニメ『「範馬刃牙」地上最強の親子喧嘩編』のオープニング/エンディング曲を収録したスプリットシングルが発売(配信は29日)、さらに9月13日には4thシングルをリリースすることも発表。今回は、1つひとつについて話を聞いた。</strong></p><p>『「範馬刃牙」地上最強の親子喧嘩編』のタイアップの話は、BE:FIRSTの『Shining One』と『Gifted.』の間に秋田書店さんから「オープニングをSKY-HI、エンディングをBE:FIRSTでどうですか？」とオファーをいただきました。親子関係、師弟関係をテーマにした作品と僕らの関係性が合っていると思っていただいたようです。</p><p>アニメの納</p><p>=== 文件名: PART2/16.md === ► 2023/08</p><h2 id="メンバーの-音楽的発露-を感じたbe-first最新作" tabindex="-1">メンバーの“音楽的発露”を感じたBE:FIRST最新作 <a class="header-anchor" href="#メンバーの-音楽的発露-を感じたbe-first最新作" aria-label="Permalink to &quot;メンバーの“音楽的発露”を感じたBE:FIRST最新作&quot;">​</a></h2><p>#マネジメント #コミュニケーション #導き #発露 #過去のトラウマ #仲間 #BEFIRST</p><h3 id="「彼らの-こうありたい-は、-音楽-に全力で向かっている。僕自身、うまくマネジメントを進められているなという安心感も強く感じた」" tabindex="-1">「彼らの“こうありたい”は、“音楽”に全力で向かっている。僕自身、うまくマネジメントを進められているなという安心感も強く感じた」 <a class="header-anchor" href="#「彼らの-こうありたい-は、-音楽-に全力で向かっている。僕自身、うまくマネジメントを進められているなという安心感も強く感じた」" aria-label="Permalink to &quot;「彼らの“こうありたい”は、“音楽”に全力で向かっている。僕自身、うまくマネジメントを進められているなという安心感も強く感じた」&quot;">​</a></h3><p><strong>2023年9月13日、BE:FIRSTは4thシングル『Mainstream』をリリースした。今回のリリースには、これまで以上にBE:FIRSTのメンバーが積極的に関わっている。初のホールツアーやフェスへの出演、『Boom Boom Back』への反響など、様々な経験を経て、BE:FIRSTはこれまで以上に「BE:FIRSTとしてどんな音楽をやりたいか」に意識が向かっていった。話し合いを重ねていたメンバーだったが、それをついにSKY-HIに打ち明けたのは、映画『BE:the ONE』の撮影で訪れていた韓国でのことだった。SKY-HIはそのとき、率直に何を感じたのだろうか。</strong></p><p>本当にうれしかったですね。BE:FIRSTの発露が音楽であってほしいと思い続けていたけれども、実際にそうなったのは最高の気分です。</p><p>=== 文件名: PART2/17.md === ► 2023/O8</p><h2 id="会社としての仕組みを確立するフェーズに来た" tabindex="-1">会社としての仕組みを確立するフェーズに来た <a class="header-anchor" href="#会社としての仕組みを確立するフェーズに来た" aria-label="Permalink to &quot;会社としての仕組みを確立するフェーズに来た&quot;">​</a></h2><p>#マネジメント #いい空気感 #ポジティブな悩み #再現可能性 #個人格と法人格 #BEFIRST</p><h3 id="「bmsgは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」" tabindex="-1">「BMSGは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」 <a class="header-anchor" href="#「bmsgは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」" aria-label="Permalink to &quot;「BMSGは、個人格のいいところで会社が動いていた。ここからは、組織としての決まり事や組織運営の部分で、しっかりと会社が動く仕組みを確立しないといけない」&quot;">​</a></h3><p><strong>2023年、BMSGの快進撃がすさまじい。BE:FIRSTの活躍に加え、MAZZELのデビュー、さらにはNovel Core24年の日本武道館公演を発表し、Aile The Shotaは初のワンマンライブを開催。edhiii boiも11月にワンマンライブを予定する。9月1日にはREIKOがプレデビューを果たし、「THE FIRST」の最終審査に残った10人が全員デビューすることになる。そればかりではない。7月に開かれた「BMSG TRAINEE Showcase2023」ではRUI、TAIKI、KANONも著しい成長を見せ、BMSGの新世代への期待も膨らませた。この状態をSKY-HIはどう見ているのか。</strong></p><p>すごい時期ですよ、アーティストが全員楽しそうっていう。どの現場に行っても空気がい</p><p>=== 文件名: PART2/18.md === ► 2023/09</p><h2 id="音楽業界の空気も変えたbmsg、3周年に思うこと" tabindex="-1">音楽業界の空気も変えたBMSG、3周年に思うこと <a class="header-anchor" href="#音楽業界の空気も変えたbmsg、3周年に思うこと" aria-label="Permalink to &quot;音楽業界の空気も変えたBMSG、3周年に思うこと&quot;">​</a></h2><p>#マネジメント #変革 #広がる共鳴 #心身の健康 #絶対的な安心 #人間的成長</p><h3 id="「『自分の居場所はここなんだ』って強く感じて安心してもらうこと、生理的安全性が完全に保たれていることっていうのは絶対に必要」" tabindex="-1">「『自分の居場所はここなんだ』って強く感じて安心してもらうこと、生理的安全性が完全に保たれていることっていうのは絶対に必要」 <a class="header-anchor" href="#「『自分の居場所はここなんだ』って強く感じて安心してもらうこと、生理的安全性が完全に保たれていることっていうのは絶対に必要」" aria-label="Permalink to &quot;「『自分の居場所はここなんだ』って強く感じて安心してもらうこと、生理的安全性が完全に保たれていることっていうのは絶対に必要」&quot;">​</a></h3><p><strong>2023年9月18日、BMSGは設立3周年を迎えた。所属アーティストはSKY-HIとNovel Coreの2人、社員は社長であるSKY-HIのみ、さらにスタッフが2人という規模で始まったBMSGは、現在、23人のアーティスト&amp;トレーニーと、50人弱の社員が所属する規模にまで拡大した。ソロアーティストは10月6日に『BUTTER FLY』でメジャーデビューを果たしたREIKOを含めて5人、グループではBE:FIRSTとMAZZEL、さらに、現在は3つ目のグループの準備も始動している。</strong></p><p><strong>そうした組織との成長とは別に、BMSGの3年間の最も大きな功績の1つは、「音楽業界の空気を変えた」ことにあるだろう。</strong></p><p>**「D.U.N.K.」などを通して果敢に取り組んできた事務所の垣根を越えたコラボレーションは、業界全体に波及してい</p><p>=== 文件名: PART2/19.md === ► 2023/10</p><h2 id="日本のエンタメを更新したかった2度目の「bmsg-fes」" tabindex="-1">日本のエンタメを更新したかった2度目の「BMSG FES」 <a class="header-anchor" href="#日本のエンタメを更新したかった2度目の「bmsg-fes」" aria-label="Permalink to &quot;日本のエンタメを更新したかった2度目の「BMSG FES」&quot;">​</a></h2><p>#BMSGFES #変革 #ライブ演出</p><h3 id="「bmsgが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」" tabindex="-1">「BMSGが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」 <a class="header-anchor" href="#「bmsgが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」" aria-label="Permalink to &quot;「BMSGが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたかった」&quot;">​</a></h3><p>「BMSG FES&#39;23」が2023年9月23日・24日に東京・東京体育館で、9月•30日10月1日に大阪・大阪城ホールで開催された。昨年の初開催では、BMSGの立ち上げからNovel Coreとの出会い、THE FIRST、BE:FIRSTの結成など、2年間の足跡を中心に物語を紡ぎ上げるようなフェスだった。2度目となる今回に新たに注力したのは何だったのか。改めてそのテーマから聞いた。</p><p>昨年のフェスは、まさにストーリーの回収のためのもの。そこまで応援してくれていた人ほど、強くストーリーを体感できるエモーショナルな良いものになったなと感じてくれたと思います。同様に、今年もストーリーの回収は最低限やらなくてはいけないものではありましたが、シンプルな回収以上に、BMSGが考えるエンタテインメントの形を打ち出し、日本のエンタテインメントの更新をしたいと考えました。</p><p>日本で「エンタテインメント」と</p><p>=== 文件名: PART2/2.md === ► 2022/12</p><h2 id="ビジネス系メディアの取材を通じて感じた自信と確信" tabindex="-1">ビジネス系メディアの取材を通じて感じた自信と確信 <a class="header-anchor" href="#ビジネス系メディアの取材を通じて感じた自信と確信" aria-label="Permalink to &quot;ビジネス系メディアの取材を通じて感じた自信と確信&quot;">​</a></h2><p>#リーダーシップ #変革 #自信 #確信</p><h3 id="「-救世主-が必要なほど日本経済や音楽業界が弱っていることが明白だったことも、結果としてはbmsgの後押しをしてくれた」から" tabindex="-1">「“救世主”が必要なほど日本経済や音楽業界が弱っていることが明白だったことも、結果としてはBMSGの後押しをしてくれた」から <a class="header-anchor" href="#「-救世主-が必要なほど日本経済や音楽業界が弱っていることが明白だったことも、結果としてはbmsgの後押しをしてくれた」から" aria-label="Permalink to &quot;「“救世主”が必要なほど日本経済や音楽業界が弱っていることが明白だったことも、結果としてはBMSGの後押しをしてくれた」から&quot;">​</a></h3><p><strong>2023年がいよいよ始まった。新しい年は、BMSGおよびSKY-HIにとってどんな1年となるのだろうか。1月13日からはBMSGの新しいボーイズグループ「MAZZEL(マーゼル)」の誕生までに迫るオーディションドキュメンタリー番組『MISSIONx2(ミッション・ミッション)』の配信がYouTubeで始まり、今春にはMAZZELがデビュー。所属アーティストの挑戦もますます積極的に進められることだろう。</strong></p><p>**オーディション「THEFIRST」での参加者の導き方やそこで語られる信念、はたまたそこからデビューしたBE:FIRSTを人気アーティストに育て上げた手腕などでも、今、SKY-HIは世の注目を集めている。最も勢いのあるマネジメントレーベルBMSGを率いる立場として、特にここ1年はビジネス系メディアから「新しいリーダー」「音楽業界の革命児」として、取材を受けることも増</p><p>=== 文件名: PART2/20.md === ► 2023/10</p><h2 id="_2度目の「bmsg-fes」、eastとwestで分けた理由" tabindex="-1">2度目の「BMSG FES」、EASTとWESTで分けた理由 <a class="header-anchor" href="#_2度目の「bmsg-fes」、eastとwestで分けた理由" aria-label="Permalink to &quot;2度目の「BMSG FES」、EASTとWESTで分けた理由&quot;">​</a></h2><p>#BMSGFES #遊び心 #チームの人間関係 #コミュニケーション #いい空気感</p><h3 id="「オールスター戦のようなシンプルな遊びの空気感を作りたかった。特にグループに関しては、既存の関係値を極力壊したかったこともある」" tabindex="-1">「オールスター戦のようなシンプルな遊びの空気感を作りたかった。特にグループに関しては、既存の関係値を極力壊したかったこともある」 <a class="header-anchor" href="#「オールスター戦のようなシンプルな遊びの空気感を作りたかった。特にグループに関しては、既存の関係値を極力壊したかったこともある」" aria-label="Permalink to &quot;「オールスター戦のようなシンプルな遊びの空気感を作りたかった。特にグループに関しては、既存の関係値を極力壊したかったこともある」&quot;">​</a></h3><p><strong>2023年9月23日・24日に東京・東京体育館で、9月30日10月1日に大阪・大阪城ホールで開催された2度目の「BMSG FES」。今回は23人に増えた所属アーティストを出身地によって「BMSG EAST」「BMSG WEST」の2つのチームに分けた。かつてあったJリーグのオールスターのような、わくわくするような非日常感を狙ったという。</strong></p><p>この分け方をしたのは、オールスター戦のようなシンプルな遊びの空気感を作りたかったからです。普段違う活動をしている人が一緒になるのもいいし、逆に、普段一緒の人が別々になるのもいい。僕自身が1番のBMSGファンだと思っているので、自分がわくわくすることは、だいたいのBMSGファンやフォロワーにわくわくしてもらえるだろうという妄信もあります(笑)。自分が心からわくわくしたものは間違</p><p>=== 文件名: PART2/21.md === 講演</p><p>► 2023年7月20日 | 日経クロストレンドFORUM 2023より</p><h2 id="続・音楽ビジネス革命-「嘘がつけない時代」のファンとの関係" tabindex="-1">続・音楽ビジネス革命：「嘘がつけない時代」のファンとの関係 <a class="header-anchor" href="#続・音楽ビジネス革命-「嘘がつけない時代」のファンとの関係" aria-label="Permalink to &quot;続・音楽ビジネス革命：「嘘がつけない時代」のファンとの関係&quot;">​</a></h2><p><strong>2023年7月20日に登壇した「日経クロストレンドFORUM 2023」のテーマは「続・音楽ビジネス革命一『嘘がつけない時代』のファンとの関係」。22年の同講演で、「今の時代のヒットに必要不可欠な要件は『嘘がないこと』」と語ったSKY-HIに、ファンとの向き合い方について聞いた。(聞き手は吾妻拓 日経クロストレンド編集委員)</strong></p><p>———— 5月に東京・代々木第一体育館で「SKY-HI ARENA TOUR 2023 -BOSSDOM」を拝見しました。エンタテインメントとして隙のないステージ構成と演出、そして迫力に感動して帰途に就いたのですが、MCでの最も印象的な言葉の1つが、「BMSGは、あなたたちと一緒に時代を変える」という宣言でした。その強烈なメッセージに鳥肌が立つ感じすらしましたが、なかでも「あなたたちと一緒に」という部分はSKY-HIさんの考え方を象徴しているんじゃないかと感じました。アーティストとしてのSKY-HI、社長としてのSKY-HI、それぞれにとってファンという</p><p>=== 文件名: PART2/3.md === ► 2022/11</p><h2 id="be-first紅白歌合戦出場の意味とaaa時代に感じたこと" tabindex="-1">BE:FIRST紅白歌合戦出場の意味とAAA時代に感じたこと <a class="header-anchor" href="#be-first紅白歌合戦出場の意味とaaa時代に感じたこと" aria-label="Permalink to &quot;BE:FIRST紅白歌合戦出場の意味とAAA時代に感じたこと&quot;">​</a></h2><p>#感覚と実態 #勢いの加速 #ビジョンの推進力 #紅白歌合戦 #BE:FIRST</p><h3 id="「今は、-実態-や-実績-を考えるうえで、数字以外のものが必要な時代だと思っている」" tabindex="-1">「今は、“実態”や“実績”を考えるうえで、数字以外のものが必要な時代だと思っている」 <a class="header-anchor" href="#「今は、-実態-や-実績-を考えるうえで、数字以外のものが必要な時代だと思っている」" aria-label="Permalink to &quot;「今は、“実態”や“実績”を考えるうえで、数字以外のものが必要な時代だと思っている」&quot;">​</a></h3><p><strong>BE:FIRSTは2022年12月31日、『第73回NHK紅白歌合戦』に初出場を果たす。設立3年目のBMSGに所属する、デビュー1周年のグループが国民的番組に出場することは、“時代が動いている”ことの象徴と言っても過言でないだろう。自身もAAAのメンバーとして過去7回出場しているSKY-HIだが、紅白に出ることの意義をどう捉えているのか。</strong></p><p>BE:FIRSTにとって紅白歌合戦の出場は、ヒットしている「感覚」に「実態」を伴わせられるまたとない機会だと考えています。AAAの場合は、ヒットしている「感覚」がない状態から出場していて、「自分らがここにいていいのだろうか」という感情もゼロではなかったんです。これといった成績もありませんでしたし。それにもかかわらず「紅白出場」という“権威”による「実態」を得たことで世間の風向きが変わっていく「感覚」は感じました。</p><p>=== 文件名: PART2/4.md === ► 2023/01</p><h2 id="mazzelを追うドキュメンタリー、エンタテインしない理由" tabindex="-1">MAZZELを追うドキュメンタリー、エンタテインしない理由 <a class="header-anchor" href="#mazzelを追うドキュメンタリー、エンタテインしない理由" aria-label="Permalink to &quot;MAZZELを追うドキュメンタリー、エンタテインしない理由&quot;">​</a></h2><p>#新プロジェクト #Mx2 #MAZZEL</p><h3 id="「今回意図したのは、エンタテインしようとしていない本当のドキュメンタリー番組であること」" tabindex="-1">「今回意図したのは、エンタテインしようとしていない本当のドキュメンタリー番組であること」 <a class="header-anchor" href="#「今回意図したのは、エンタテインしようとしていない本当のドキュメンタリー番組であること」" aria-label="Permalink to &quot;「今回意図したのは、エンタテインしようとしていない本当のドキュメンタリー番組であること」&quot;">​</a></h3><p><strong>SKY-HI率いるBMSGが放つ2つ目の男性ダンス&amp;ボーカルグループ「MAZZEL(マーゼル)」の誕生までを追うオーディションドキュメンタリー番組「MISSIONx2(ミッション・ミッション、以下Mx2)」が、BMSG YouTube公式チャンネルで配信中だ。1月の配信ではまずBMSGにトレーニーとして所属していたRANと結果的には別の道を選んだREIKO、さらに電撃的に、非公開トレーニーだったSEITOとKAIRYUの存在が明かされ、4人の物語が幕を開けた。まずは「THE FIRST」の3次審査までいたKAIRYUの話から。</strong></p><p>番組でも話していますが、「THE FIRST」に参加してくれていたKAIRYUが、オーディション後、会社宛てにメールを送ってくれました。スキルの足りなかったダンスにも意欲的に取り組んでいて基礎練習の動画も送ってくれ、「これはひょっとしたら何かになってくれる気がする」</p><p>=== 文件名: PART2/5.md === ► 2023/01</p><h2 id="_2つ目のボーイズグループ「mazzel」を今作る理由" tabindex="-1">2つ目のボーイズグループ「MAZZEL」を今作る理由 <a class="header-anchor" href="#_2つ目のボーイズグループ「mazzel」を今作る理由" aria-label="Permalink to &quot;2つ目のボーイズグループ「MAZZEL」を今作る理由&quot;">​</a></h2><p>#新プロジェクト #Mx2 #MAZZEL #焦り #迷路の抜け道 #幸せ</p><h3 id="「もう本当にめちゃくちゃ焦っていました。物事ってやると動くけど、やらないと動かないじゃないですか。やらないと進まないから」" tabindex="-1">「もう本当にめちゃくちゃ焦っていました。物事ってやると動くけど、やらないと動かないじゃないですか。やらないと進まないから」 <a class="header-anchor" href="#「もう本当にめちゃくちゃ焦っていました。物事ってやると動くけど、やらないと動かないじゃないですか。やらないと進まないから」" aria-label="Permalink to &quot;「もう本当にめちゃくちゃ焦っていました。物事ってやると動くけど、やらないと動かないじゃないですか。やらないと進まないから」&quot;">​</a></h3><p><strong>SKY-HIが率いるBMSGの2つ目のダンス&amp;ボーカルグループ「MAZZEL(マーゼル)」の誕生を追ったオーディションドキュメンタリー番組「MISSIONx2」(以下、「Mx2」)が配信中だ。</strong></p><p>**BE:FIRSTが誕生したオーディション「THE FIRST」後にトレーニーとなったRANとREIKOは、オーディション後に様々な活動を行ってきた。RANは21年9月・10月、22年1月に舞台「絶対青春合唱コメディ『SING!!!』で主演を務め、REIKOは21年10月にSKY-HIの『One More Day feat.REIKO』に参加。彼はSKY-HIと共に『スッキリ』にも出演し、その後、SKY-HIのホールツアー『SKY-HI HALL TOUR 2022-八面六臂-』9公演に帯同した。21年11月・12月には2人そろってファッショ</p><p>=== 文件名: PART2/6.md === ► 2023/01</p><h2 id="「好き-好き」を実現する-身体性のために" tabindex="-1">「好き=好き」を実現する 身体性のために <a class="header-anchor" href="#「好き-好き」を実現する-身体性のために" aria-label="Permalink to &quot;「好き=好き」を実現する 身体性のために&quot;">​</a></h2><p>#新プロジェクト #変革 #DUNK #身体性 #いい空気感</p><h3 id="「身体的・本能的に『好き-好き』でいられる空間は絶対にもっと広がったほうがいい」" tabindex="-1">「身体的・本能的に『好き=好き』でいられる空間は絶対にもっと広がったほうがいい」 <a class="header-anchor" href="#「身体的・本能的に『好き-好き』でいられる空間は絶対にもっと広がったほうがいい」" aria-label="Permalink to &quot;「身体的・本能的に『好き=好き』でいられる空間は絶対にもっと広がったほうがいい」&quot;">​</a></h3><p><strong>2月にSKY-HIによるダンス&amp;ボーカルの大型プロジェクト「D.U.N.K.」が始動した。日本テレビで毎週される放送に加え、3月にはアリーナ規模でのライブが3公演、さらには今後各種SNSでの発信も絡めて、立体的に展開する。参加アーティストにはLDHのGENERATIONS、BALLISTIK BOYZ、HYBE JAPANの&amp;TEAM、ソロアーティストのAyumu Imazu、BMSGからSKY-HI、BE:FIRST、AileTheShota、REIKO、そして大御所のDREAMS COME TRUEなど、ダンス&amp;ボーカルの「今」を象徴する幅広いメンバーがそろった。プロジェクトの軸にあるのはダンスだ。</strong></p><p>これまでの日本の音楽番組って、パフォーマンスに身体性があまりないなと思っていたんです。そもそも日本のボーイズグループ市場は、本当にすごく特殊であり閉鎖的だと思うんです。何か開けたものをやりたい感じ</p><p>=== 文件名: PART2/7.md === ► 2023/02</p><h2 id="be-firstに課す「大きな夢」のためのマイルストーン" tabindex="-1">BE:FIRSTに課す「大きな夢」のためのマイルストーン <a class="header-anchor" href="#be-firstに課す「大きな夢」のためのマイルストーン" aria-label="Permalink to &quot;BE:FIRSTに課す「大きな夢」のためのマイルストーン&quot;">​</a></h2><p>#BE:FIRST #夢の大切さを作り続け</p><h3 id="「『目標』は可能なことを実現する可能性を膨らませてれるけれども、『夢』は不可能を可能にする可能性があるもの」" tabindex="-1">「『目標』は可能なことを実現する可能性を膨らませてれるけれども、『夢』は不可能を可能にする可能性があるもの」 <a class="header-anchor" href="#「『目標』は可能なことを実現する可能性を膨らませてれるけれども、『夢』は不可能を可能にする可能性があるもの」" aria-label="Permalink to &quot;「『目標』は可能なことを実現する可能性を膨らませてれるけれども、『夢』は不可能を可能にする可能性があるもの」&quot;">​</a></h3><p><strong>2月に19都市27公演を巡る「BE:FIRST 1st One Man Tour “BE:1&quot; 2022-2023」を終えたBE:FIRST。ホール公演から始まりアリーナで締めたこのツアーで、BE:FIRSTはさらに大きく成長し、堂々たるステージを見せた。ライブの最後には「近い未来にドームでのライブができるアーティストになります」という力強い宣言もあり、今後への期待を大きく膨らませた。「デビューから1年ちょっとしかたってないとは到底思えなかった」とSKY-HIに話すと、「ですよね?」と言いながらも、社長として冷静な一面を覗かせた。</strong></p><p>ご覧いただいたようなライブを1年目から最低限できないといけないっていうのは、数ある目標のなかでも絶対にやらなくてはならないことでした。自分が目指していること、彼らが目指していることはもっと先にあるので、これはあくまでもマイルストーンの1つです。</p><p>=== 文件名: PART2/8.md === ► 2023/03</p><h2 id="bmsgを支えるb-town、その重要性とリニューアルの狙い" tabindex="-1">BMSGを支えるB-Town、その重要性とリニューアルの狙い <a class="header-anchor" href="#bmsgを支えるb-town、その重要性とリニューアルの狙い" aria-label="Permalink to &quot;BMSGを支えるB-Town、その重要性とリニューアルの狙い&quot;">​</a></h2><p>#ファンコミュニティ #オンラインサロン #コミュニケーション #発信の方法 #B-TOWN</p><h3 id="「本来、コミュニケーションって前提条件や相手の状況によって全く違うアプローチをしないといけないと思う」" tabindex="-1">「本来、コミュニケーションって前提条件や相手の状況によって全く違うアプローチをしないといけないと思う」 <a class="header-anchor" href="#「本来、コミュニケーションって前提条件や相手の状況によって全く違うアプローチをしないといけないと思う」" aria-label="Permalink to &quot;「本来、コミュニケーションって前提条件や相手の状況によって全く違うアプローチをしないといけないと思う」&quot;">​</a></h3><p><strong>BMSG設立から間もない2020年10月10日に始まったファンコミュニティ「B-Town」。月額5000円の「Architect」と月額500円の「Resident」の2つのコースがあり、「Architect」ではBMSGの経営や今後の展開など、まだ世に発表されていない貴重な話が聞けるとともに、SKY-HIの手記やアーティストのインスタライブ、スタッフの話など、ここだけのコンテンツが発信されている。まだ歴史の浅いBMSGが、応援してくれるファンと共に歩んでいくような意味合いも強い。</strong></p><p><strong>その「B-Town」が、23年3月、新たにオンラインサロンとして仕切り直しを行った。テコ入れに着手したのはなぜなのか。まずは、改めて当初「B-Town」の運営を決めた理由から聞いた。</strong></p><p>「B-Town」を立ち上げた理由はたくさんあるのです</p><p>=== 文件名: PART2/9.md === ► 2023/04</p><h2 id="sky-hiが語るmazzel新たなオーディションで目指したもの" tabindex="-1">SKY-HIが語るMAZZEL新たなオーディションで目指したもの <a class="header-anchor" href="#sky-hiが語るmazzel新たなオーディションで目指したもの" aria-label="Permalink to &quot;SKY-HIが語るMAZZEL新たなオーディションで目指したもの&quot;">​</a></h2><p>#MAZZEL #いい空気感 #バズ #守りと攻め #プロとしての自覚</p><h3 id="「-buzz-と-bomb-って隣り合わせな気がする。大きなbuzzを起こすことよりも、「守る」ことを意識した」" tabindex="-1">「“buzz”と“bomb”って隣り合わせな気がする。大きなbuzzを起こすことよりも、「守る」ことを意識した」 <a class="header-anchor" href="#「-buzz-と-bomb-って隣り合わせな気がする。大きなbuzzを起こすことよりも、「守る」ことを意識した」" aria-label="Permalink to &quot;「“buzz”と“bomb”って隣り合わせな気がする。大きなbuzzを起こすことよりも、「守る」ことを意識した」&quot;">​</a></h3><p><strong>2023年5月17日、BE:FIRSTに次ぐBMSG2つ目のグループとしてMAZZEL(マーゼル)がデビューを果たした。3月のデビュー記者会見から1カ月弱、この間に数回SKY-HIと顔を合わせる機会があった。相変わらず多忙を極め、様々なことに精力的に挑んでいるようだが、ことMAZZELの話になるとひと際表情が明るくなり、実に楽しそうな笑顔を見せるように感じた。テレビ出演でのパフォーマンスや彼らの現場での様子を話しながら、「楽しい」「素晴らしい」と、会うたびに変わる彼らの成長への喜びを口にする。</strong></p><p>昨日もMAZZELの現場に行ってきたんですが、今、本当にMAZZELはメンバー間の空気がすごく良いんです。「THEFIRST」の頃とは会社の状況が全然違うなと感じたのは、ユニバーサルさんを含めて最初からみんなすごく前のめりでやってくださる関係値が</p><p>=== 文件名: PART3/0.md ===</p><h2 id="part-3" tabindex="-1">PART 3 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;PART 3&quot;">​</a></h2><p>2024年のBMSG</p><p>01/17 Novel Coreが初の武道館公演を開催</p><p>02/13 「BMSGから音楽業界を持続不可能にしないための提言」を発信</p><p>03/02,03 BE:FIRSTが初の東京ドーム公演。4月20日、21日には京セラドーム大阪公演も</p><p>04/15 2度目となるビジネスカンファレンス「Greeting &amp; Gathering&#39;24」開催</p><p>04/24 BE:FIRSTがシングル『Masterplan』リリース。CD製造段階からプラスチック使用を大幅に削減、CDに付いていた特典を減らし、その特典に値するグッズを直接販売することなどの試みを試験的に導入</p><p>05/01 SKY-HIが企画に参加した新音楽番組『Apartment B』の放送スタート</p><p>05/29 SKY-HI、Novel Core、Aile The Shota、edhiii boi、REIKOの5人によるBMSG POSSEが『Girlfriend』を配信</p><p>06/01 MAZZELが初の全国ツアー「MAZZEL 1st One Man Tour 2024 &quot;Join us in the PARADE&quot;」をスタ</p><p>=== 文件名: PART3/1.md === ► 2023/11</p><h2 id="ガールズオーディションはより理想的に歩むための一歩" tabindex="-1">ガールズオーディションはより理想的に歩むための一歩 <a class="header-anchor" href="#ガールズオーディションはより理想的に歩むための一歩" aria-label="Permalink to &quot;ガールズオーディションはより理想的に歩むための一歩&quot;">​</a></h2><p>#新プロジェクト #マスタープラン #ノノガ #ちゃんみな</p><h3 id="「自分がこれまで諸々のギャップで苦しめられてきたにもかかわらず、ジェンダーギャップの促進につながりかねないことをやってるんじゃないかという自責の念も感じていた」" tabindex="-1">「自分がこれまで諸々のギャップで苦しめられてきたにもかかわらず、ジェンダーギャップの促進につながりかねないことをやってるんじゃないかという自責の念も感じていた」 <a class="header-anchor" href="#「自分がこれまで諸々のギャップで苦しめられてきたにもかかわらず、ジェンダーギャップの促進につながりかねないことをやってるんじゃないかという自責の念も感じていた」" aria-label="Permalink to &quot;「自分がこれまで諸々のギャップで苦しめられてきたにもかかわらず、ジェンダーギャップの促進につながりかねないことをやってるんじゃないかという自責の念も感じていた」&quot;">​</a></h3><p><strong>ガールズグループのメンバーを発掘するオーディション「GIRLS GROUP AUDITION PROJECT 2024『No No Girls』」(以下、「No No Girls」)が進行中だ。既に応募は締め切られ、選考がこれから本格的にスタートする。本プロジェクトではBMSGがちゃんみなをプロデューサーに迎え、オーディションから生まれたガールズグループが所属する新たなマネジメント組織をBMSG傘下に設置する。</strong></p><p>**「No No Girls」のホームページで、ちゃんみなは「私は今まで沢山、様々な場面で“No”と言われて来ました。それでも自分の魂の声を聞いて歌って踊ってきました。私の様な経験をした方、または自分で自分に“No”と言い続けている方、この“No”をどう受け止めるかは任せますが、様々な視点やドラマがあっ</p><p>=== 文件名: PART3/10.md === ► 2024/06</p><h2 id="be-firstとateezのコラボレーションが実現するまで" tabindex="-1">BE:FIRSTとATEEZのコラボレーションが実現するまで <a class="header-anchor" href="#be-firstとateezのコラボレーションが実現するまで" aria-label="Permalink to &quot;BE:FIRSTとATEEZのコラボレーションが実現するまで&quot;">​</a></h2><p>#BEFIRST #初海外ステージ #日本発 #みんなで世界へ</p><h3 id="「日本のシーンに世界から注目してもらえるような大きなうねりを作るためには、複数の会社が手を携えて進める必要性は強く感じている」" tabindex="-1">「日本のシーンに世界から注目してもらえるような大きなうねりを作るためには、複数の会社が手を携えて進める必要性は強く感じている」 <a class="header-anchor" href="#「日本のシーンに世界から注目してもらえるような大きなうねりを作るためには、複数の会社が手を携えて進める必要性は強く感じている」" aria-label="Permalink to &quot;「日本のシーンに世界から注目してもらえるような大きなうねりを作るためには、複数の会社が手を携えて進める必要性は強く感じている」&quot;">​</a></h3><p><strong>2024年6月下旬、BE:FIRSTと韓国の8人組ボーイズグループATEEZ(エイティーズ)とのコラボレーションが突如発表された。ATEEZは、23年12月にリリースした2ndフルアルバム『THEWORLDEP.FIN:WILL』が、米・Billboardのメーンチャート「Billboard 200」にて1位、英オフィシャルアルバムチャートにて2位を獲得。さらに、今年4月には韓国のボーイズグループとして初めて米国最大級の音楽フェスティバル「コーチェラ・フェスティバル」のステージに立つなど、韓国で最も勢いのあるボーイズグループの1組だ。</strong></p><p>**実は、23年12月にはSKY-HIがプロデュースするダンス&amp;ボーカルのイベント「D.U.N.K.Showcase」の京セラドーム公演に出演するなど、表から見える縁はあった。しかし、ステージ出演と</p><p>=== 文件名: PART3/11.md === ► 2024/07</p><h2 id="デビュー1年で「自己肯定感」と「自尊心」が育ったmazzel" tabindex="-1">デビュー1年で「自己肯定感」と「自尊心」が育ったMAZZEL <a class="header-anchor" href="#デビュー1年で「自己肯定感」と「自尊心」が育ったmazzel" aria-label="Permalink to &quot;デビュー1年で「自己肯定感」と「自尊心」が育ったMAZZEL&quot;">​</a></h2><p>#リーダーシップ #成長 #プロデュース #自己肯定感 #MAZZEL</p><h3 id="「個々の自己肯定感や自尊心といったものがある程度備わらないと、近くにいる他者の肯定にもつながらない」" tabindex="-1">「個々の自己肯定感や自尊心といったものがある程度備わらないと、近くにいる他者の肯定にもつながらない」 <a class="header-anchor" href="#「個々の自己肯定感や自尊心といったものがある程度備わらないと、近くにいる他者の肯定にもつながらない」" aria-label="Permalink to &quot;「個々の自己肯定感や自尊心といったものがある程度備わらないと、近くにいる他者の肯定にもつながらない」&quot;">​</a></h3><p><strong>MAZZELがデビューして1年。2024年6、7月に全国ツアー『MAZZEL 1st One Man Tour 2024 “Join us in the PARADE”』で8都市9公演を巡り、さらに10月に追加公演でアリーナでの開催も発表された。「初ツアーを経て大きく伸びる」ことは新人グループの定石。とはいえ、ツアー最終地の東京公演で見た彼らには、スキルやパフォーマンスの成長以上に見えたものがあった。自分たちがやっていることへの自信やライブの場を楽しんでいる姿が印象深く、彼らの強みである「個性」の輪郭をより明確にしてきたように感じた。SKY-HI自身は、現在の彼らをどう捉えているのか。</strong></p><p>「最初のツアーが終わるタイミングで今のような「（グループの）内側が仲がいい』という空気になるといいな」というのはすごくあったので、そうなれたことはうれしいですね。「</p><p>=== 文件名: PART3/12.md === ► 2024/08</p><h2 id="be-firstの2ndアルバムで社会に見せたかったマインド" tabindex="-1">BE:FIRSTの2ndアルバムで社会に見せたかったマインド <a class="header-anchor" href="#be-firstの2ndアルバムで社会に見せたかったマインド" aria-label="Permalink to &quot;BE:FIRSTの2ndアルバムで社会に見せたかったマインド&quot;">​</a></h2><p>#リーダーシップ #成長 #プロデュース #BEFIRST</p><h3 id="「僕が意識しなくてはいけないのは、彼らの成長の機会をつくる責務があるということ」" tabindex="-1">「僕が意識しなくてはいけないのは、彼らの成長の機会をつくる責務があるということ」 <a class="header-anchor" href="#「僕が意識しなくてはいけないのは、彼らの成長の機会をつくる責務があるということ」" aria-label="Permalink to &quot;「僕が意識しなくてはいけないのは、彼らの成長の機会をつくる責務があるということ」&quot;">​</a></h3><p><strong>BE:FIRSTの2ndアルバム『2:BE』が、2024年8月28日にリリースされた。発売に先立って先行配信されたリード曲『Blissful』は、8月21日公開のBillboard JAPAN総合ソング・チャートJAPAN Hot 100の1位をはじめ、各種音楽チャート185冠を達成している。</strong></p><p><strong>1stアルバム『BE:1』からちょうど2年。この間に、BE:FIRSTは東阪での初のドーム公演で大成功を収め、今や押しも押されもせぬ日本を代表するボーイズグループの1組となった。同時に『Boom Boom Back』以降、『Mainstream』と『Masterplan』を経て彼らのアーティストとしての自我が急速に成長したことで、新章の幕開けとも言える2ndアルバムでどんな姿を見せてくれるのかに期待が集まっていた。SKY-HIはこのアルバムをどんなコンセプト、位置づけと考えているのか。</strong></p><p>=== 文件名: PART3/13.md === ► 2024/08</p><h2 id="be-first初の海外公演で感じた大きな手応えと収穫" tabindex="-1">BE:FIRST初の海外公演で感じた大きな手応えと収穫 <a class="header-anchor" href="#be-first初の海外公演で感じた大きな手応えと収穫" aria-label="Permalink to &quot;BE:FIRST初の海外公演で感じた大きな手応えと収穫&quot;">​</a></h2><p>#グローバル #日本から世界へ #ビジョンの共有 #BEFIRST</p><h3 id="「ずっと言っていますが、僕はbmsgをアジアで1番有名な会社にしたいし、bmsgのアーティストたちをアジアで1番勢いのあるアーティストにしたい」" tabindex="-1">「ずっと言っていますが、僕はBMSGをアジアで1番有名な会社にしたいし、BMSGのアーティストたちをアジアで1番勢いのあるアーティストにしたい」 <a class="header-anchor" href="#「ずっと言っていますが、僕はbmsgをアジアで1番有名な会社にしたいし、bmsgのアーティストたちをアジアで1番勢いのあるアーティストにしたい」" aria-label="Permalink to &quot;「ずっと言っていますが、僕はBMSGをアジアで1番有名な会社にしたいし、BMSGのアーティストたちをアジアで1番勢いのあるアーティストにしたい」&quot;">​</a></h3><p><strong>7月20日、21日、BE:FIRSTは、韓国の男性ダンス&amp;ボーカルグループATEEZがBMOスタジアムで開催した米LA公演で、スペシャルゲストとしてオープニングアクトを務めた。</strong></p><p>**このステージは、BE:FIRSTのキャリア初の海外ステージ。ライブに先立って、7月1日に両者はコラボ曲『Hush-Hush』をリリースしており、双方コラボ相手に対し親近感や理解を深めているなかでの“共演”。当日はBE:FIRSTがステージに姿を現すと、会場のATINY(ATEEZのファンネーム)は盛大な拍手と歓声とともに立ち上がった。そして音楽にノって大きく体を揺らし、一挙手一投足に拍手し、声を上げ、大きな盛り上がりを見せた。実は彼らがオープニングアクトを務めることに対しては日韓の一部からは反発もあったが、そんな空気を吹き飛ばすようなア</p><p>=== 文件名: PART3/14.md === ► 2024/09</p><h2 id="夏フェス総括2024カルチャー創造のための必要要件" tabindex="-1">夏フェス総括2024カルチャー創造のための必要要件 <a class="header-anchor" href="#夏フェス総括2024カルチャー創造のための必要要件" aria-label="Permalink to &quot;夏フェス総括2024カルチャー創造のための必要要件&quot;">​</a></h2><p>#カルチャー創造 #リスペクト #BEFIRST #BMSGPOSSE</p><h3 id="「僕らはただ売れればいいのではなく、新しいカルチャ一を作るために活動している。そのためには他のカルチャーからリスペクトされる存在にならなくちゃいけない」" tabindex="-1">「僕らはただ売れればいいのではなく、新しいカルチャ一を作るために活動している。そのためには他のカルチャーからリスペクトされる存在にならなくちゃいけない」 <a class="header-anchor" href="#「僕らはただ売れればいいのではなく、新しいカルチャ一を作るために活動している。そのためには他のカルチャーからリスペクトされる存在にならなくちゃいけない」" aria-label="Permalink to &quot;「僕らはただ売れればいいのではなく、新しいカルチャ一を作るために活動している。そのためには他のカルチャーからリスペクトされる存在にならなくちゃいけない」&quot;">​</a></h3><p><strong>今夏は毎週末、様々なロックフェスでBMSGのアーティストたちが会場を沸かせた。特にBE:FIRSTは「SUMMER SONIC2024」のマウンテンステージや「音楽と髭達2024」のヘッドライナー、「ROCK IN JAPAN FESTIVAL 2024 in HITACHINAKA」のGRASSステージのトップバッターなどを務め、観客をうならせた。思い返すと、初のロックフェス出演は22年5月の「VIVA LA ROCK」。ボーイズグループにとってアウェーであるロックフェスのステージに立つに当たり、SKY-HIは彼らに、オープニングでダンス抜きのパワフルな新曲を披露すること、観客の心をつかむMCをすることなどの課題を与えた。あれから2年、今やフェスアーティストとしての確固たる立場を築いたと言えるだろう。</strong></p><p>当時か</p><p>=== 文件名: PART3/15.md === 講演</p><p>► 2024年7月25日 | 日経クロストレンドFORUM 2024より</p><h2 id="続・音楽ビジネス革命bmsgの日本再興プラン" tabindex="-1">続・音楽ビジネス革命BMSGの日本再興プラン <a class="header-anchor" href="#続・音楽ビジネス革命bmsgの日本再興プラン" aria-label="Permalink to &quot;続・音楽ビジネス革命BMSGの日本再興プラン&quot;">​</a></h2><p><strong>2024年7月25日に登壇した「日経クロストレンドFORUM2024」のテーマは「続・音楽ビジネス革命BMSGの日本再興プラン」。20年に設立した自身の会社BMSGは2グループ、5ソロアーティストを擁する規模に大きく成長。「BE:FIRST」はデビュー2年4カ月でドーム公演も成功させた。指揮を執るSKY-HIが「準備は整った」と語るのはグローバル展開。今なぜ世界に向かうのか。BMSGの未来像を解き明かす。(聞き手は吾妻拓 日経クロストレンド編集委員)</strong></p><p>———— BMSGはこの1年でさらに会社そのものが大きくなり、所属アーティストの数も増えました。グループが2組、ソロアーティストが5人、トレーニーが3人・・・。</p><p>こうやってアーティスト写真を並べると、ソロアーティストたちのバラバラさが最高ですね。1人として同じトーンがない。BMSG=BeMySelfGroupということで、アーティストなどが自分自身のままいられる環境を作ることをモットーにしていますが、写真だけでもBMSGらしさが伝わって</p><p>=== 文件名: PART3/2.md === ► 2023/12</p><h2 id="nissyとのコラボ曲で届けたかったテーマとは" tabindex="-1">Nissyとのコラボ曲で届けたかったテーマとは？ <a class="header-anchor" href="#nissyとのコラボ曲で届けたかったテーマとは" aria-label="Permalink to &quot;Nissyとのコラボ曲で届けたかったテーマとは？&quot;">​</a></h2><p>#DUNK #リーダーシップ #他社とのコラボ #キャリア #アイドル論 #SNSカルチャー</p><h3 id="「キャリアと歴史がある自分こそはちゃんと反論や否定をしないといけない」" tabindex="-1">「キャリアと歴史がある自分こそはちゃんと反論や否定をしないといけない」 <a class="header-anchor" href="#「キャリアと歴史がある自分こそはちゃんと反論や否定をしないといけない」" aria-label="Permalink to &quot;「キャリアと歴史がある自分こそはちゃんと反論や否定をしないといけない」&quot;">​</a></h3><p><strong>2023年12月2日、3日に京セラドーム大阪にてSKY-HI主宰のライブイベント「D.U.N.K. Showcase in KYOCERA DOME OSAKA」が開催された。日本テレビとタッグを組んだダンス&amp;ボーカルの大型プロジェクト「D.U.N.K.」のライブとしては23年3月に続き2度目。プロジェクトが掲げる「良いものは良い/もうダンス&amp;ボーカルシーンに垣根も差別も必要ない/ここを歴史のターニングポイントにしよう」の具現化はパワーアップし、所属事務所やレーベルの枠を超えた12組のアーティストがステージに立った。</strong></p><p><strong>ダンス&amp;ボーカルのコラボステージを盛り込んだイベントは、過去にないもの。1度目のショーケース後、SKY-HIは「ようやくどんなイベントなのかを伝えやすくなると思う」と話していたが、2回目を終えた今、前回と1番違ったのはそこだったと振り返る。</strong></p><p>=== 文件名: PART3/3.md === ► 2024/01</p><h2 id="bmsg設立時からの夢だったnovel-core武道館の意味" tabindex="-1">BMSG設立時からの夢だったNovel Core武道館の意味 <a class="header-anchor" href="#bmsg設立時からの夢だったnovel-core武道館の意味" aria-label="Permalink to &quot;BMSG設立時からの夢だったNovel Core武道館の意味&quot;">​</a></h2><p>#マスタープラン #Novel Core #夢 #コミュニケーション #導き</p><h3 id="「-大人の思惑-が含まれていると、見ている方々に伝わるし、特に若い世代の方は無意識かもしれないけれど敏感に嗅ぎ取るもの」" tabindex="-1">「“大人の思惑”が含まれていると、見ている方々に伝わるし、特に若い世代の方は無意識かもしれないけれど敏感に嗅ぎ取るもの」 <a class="header-anchor" href="#「-大人の思惑-が含まれていると、見ている方々に伝わるし、特に若い世代の方は無意識かもしれないけれど敏感に嗅ぎ取るもの」" aria-label="Permalink to &quot;「“大人の思惑”が含まれていると、見ている方々に伝わるし、特に若い世代の方は無意識かもしれないけれど敏感に嗅ぎ取るもの」&quot;">​</a></h3><p><strong>2024年1月17日、22歳最後の日に、Novel Coreは日本武道館での単独公演で、彼のこれまでのストーリーを語り上げる素晴らしいステージを見せた。BMSGアーティストたちと共に客席にいたSKY-HIは、こぶしを上げ、歓声を上げ、時に涙を見せながら、Novel Coreを見守っていた。</strong></p><p><strong>17年のSKY-HIの武道館公演を見てこのステージに立つことを夢見たNovel Coreは、20年、「才能を殺さない」を掲げたBMSGの第1弾アーティストとして契約。以降、2人は「夢」に向かって1つひとつ積み重ねてきた。今回の取材は、武道館公演の約10時間後。興奮が残るなかでの心境を聞いた。</strong></p><p>最初は「自分も(武道館の)ステージに立つのかな」と思っていたんですよ。でも、コア(Novel Core)が「今回は出ないで、(客席で</p><p>=== 文件名: PART3/4.md === ► 2024/02</p><h2 id="bmsgが発した音楽業界を持続不可能にしないための提言" tabindex="-1">BMSGが発した音楽業界を持続不可能にしないための提言 <a class="header-anchor" href="#bmsgが発した音楽業界を持続不可能にしないための提言" aria-label="Permalink to &quot;BMSGが発した音楽業界を持続不可能にしないための提言&quot;">​</a></h2><p>#新プロジェクト #SDGs #CD多売ビジネスへの反旗</p><h3 id="「世の中に『これはおかしい』『変えなくてはいけない』と提言するのは、僕らのようなベンチャー企業の役割。そもそもより良い社会のために起業しているわけだから」" tabindex="-1">「世の中に『これはおかしい』『変えなくてはいけない』と提言するのは、僕らのようなベンチャー企業の役割。そもそもより良い社会のために起業しているわけだから」 <a class="header-anchor" href="#「世の中に『これはおかしい』『変えなくてはいけない』と提言するのは、僕らのようなベンチャー企業の役割。そもそもより良い社会のために起業しているわけだから」" aria-label="Permalink to &quot;「世の中に『これはおかしい』『変えなくてはいけない』と提言するのは、僕らのようなベンチャー企業の役割。そもそもより良い社会のために起業しているわけだから」&quot;">​</a></h3><p><strong>2024年2月13日、BMSGは「BMSGから音楽業界を持続不可能にしないための提言」と題して2200文字以上に及ぶメッセージを発信した。起業当初からSKY-HIは、音楽業界におけるCDビジネスの在り方に対して警鐘を鳴らしてきたが、今回はBMSGとしてのアクションを掲げることによって、さらに強い意志を打ち出したと言えるだろう。</strong></p><p><strong>具体的には、4月24日にBE:FIRSTがリリースするシングルにおいて、「CDの製造段階からプラスチックの使用を減らすこと」と「これまでCDに付いていた様々な特典を減らし、直接その特典に値するグッズを販売する仕組みを試験的に導入すること」を発表。それを打ち出す思いについては、SKY-HIの名前で出した提言を読むことが1番だろうが、果たしてその反響はどのようなものだったのか。</strong></p><p>今</p><p>=== 文件名: PART3/5.md === ► 2024/03</p><h2 id="初の東京ドーム公演を終えたbe-first、次のフェーズは" tabindex="-1">初の東京ドーム公演を終えたBE:FIRST、次のフェーズは？ <a class="header-anchor" href="#初の東京ドーム公演を終えたbe-first、次のフェーズは" aria-label="Permalink to &quot;初の東京ドーム公演を終えたBE:FIRST、次のフェーズは？&quot;">​</a></h2><p>#信用 #プロフェッショナリズム #日本の未来 #自覚 #日本代表 #BEFIRST</p><h3 id="「be-firstと将来の目標を共有する場合、それは目標でもあるけれど必達条件でもある。ふわっとした言葉になりがちな-世界-という言葉を、具体的に説明する必要がある」" tabindex="-1">「BE:FIRSTと将来の目標を共有する場合、それは目標でもあるけれど必達条件でもある。ふわっとした言葉になりがちな“世界”という言葉を、具体的に説明する必要がある」 <a class="header-anchor" href="#「be-firstと将来の目標を共有する場合、それは目標でもあるけれど必達条件でもある。ふわっとした言葉になりがちな-世界-という言葉を、具体的に説明する必要がある」" aria-label="Permalink to &quot;「BE:FIRSTと将来の目標を共有する場合、それは目標でもあるけれど必達条件でもある。ふわっとした言葉になりがちな“世界”という言葉を、具体的に説明する必要がある」&quot;">​</a></h3><p><strong>2024年3月2日と3日、BE:FIRSTは自身初の東京ドーム公演を開催し、2日間で約10万人を動員。初のドーム公演とは思えないほど堂々たる姿で、圧巻のパフォーマンスを披露した。取材は京セラドーム公演前だったため、具体的な演出等のネタバレを避けながら、まずは結成時からの目標だった東京ドーム公演の意義を改めて話してもらった。</strong></p><p>3年準備してきた日だったので、当然万感の思いでしたが、同時に心配はいっぱいありました。ドームを借りられるのは3日間だけですから、前日の建て込み(セットの組み立て)が間に合うのかも、現場でのリハーサルが十分にできない状態で本番に臨まなきゃいけないことも・・・もう全て心配でしたね。メンバーも東京ドームは初めてのステージ。それなのに、動線やシミュレーション</p><p>=== 文件名: PART3/6.md === ► 2024/03</p><h2 id="be-first東京ドーム公演の演出・選曲に込めた意図演出" tabindex="-1">BE:FIRST東京ドーム公演の演出・選曲に込めた意図演出 <a class="header-anchor" href="#be-first東京ドーム公演の演出・選曲に込めた意図演出" aria-label="Permalink to &quot;BE:FIRST東京ドーム公演の演出・選曲に込めた意図演出&quot;">​</a></h2><p>#ブロデュース #BEFIRST #初ドーム</p><h3 id="「エモーショナルになるあまり、-ドームが最高到達点-に見えることは絶対に避けなくてはいけなかった」" tabindex="-1">「エモーショナルになるあまり、“ドームが最高到達点”に見えることは絶対に避けなくてはいけなかった」 <a class="header-anchor" href="#「エモーショナルになるあまり、-ドームが最高到達点-に見えることは絶対に避けなくてはいけなかった」" aria-label="Permalink to &quot;「エモーショナルになるあまり、“ドームが最高到達点”に見えることは絶対に避けなくてはいけなかった」&quot;">​</a></h3><p><strong>BE:FIRSTの初ドーム公演「BE:FIRST LIVE in DOME 2024 “Mainstream-Masterplan”」が、2024年7月12日0時からAmazon Prime Videoで世界配信される。BE:FIRSTはドーム公演の直前まで9都市22公演のアリーナツアーを回っていた。しかし、ドーム公演の演出やセットリストは、メジャーデビュ一曲『Gifted.』で幕を開けるなど、アリーナツアー以上に彼らが生まれたオーディション「THE FIRST」から始まったここまでのBE:FIRSTのストーリーが色濃く出たものになっていたように思えた。</strong></p><p>今後、新たにBE:FIRSTのファンになった人や興味を持った人が公演の映像パッケージを買ってくれた際に、「入門編」としてBE:FIRSTのストーリーがしっかり伝わるものにしたいと考えていました。実を言えば当初、BE:FIRST</p><p>=== 文件名: PART3/7.md === ► 2024/04</p><h2 id="ずっとやりたかった-本当の意味での音楽番組-がスタート" tabindex="-1">ずっとやりたかった“本当の意味での音楽番組”がスタート <a class="header-anchor" href="#ずっとやりたかった-本当の意味での音楽番組-がスタート" aria-label="Permalink to &quot;ずっとやりたかった“本当の意味での音楽番組”がスタート&quot;">​</a></h2><p>#新プロジェクト #新音楽番組 #本質的</p><h3 id="「良いもの、-これ、いいね-というものはキャッチー。だから結果として広がる気はしている」" tabindex="-1">「良いもの、“これ、いいね！”というものはキャッチー。だから結果として広がる気はしている」 <a class="header-anchor" href="#「良いもの、-これ、いいね-というものはキャッチー。だから結果として広がる気はしている」" aria-label="Permalink to &quot;「良いもの、“これ、いいね！”というものはキャッチー。だから結果として広がる気はしている」&quot;">​</a></h3><p><strong>SKY-HIが企画に参加した新音楽番組『Apartment B(アパートメント・ビ一)』が、2024年5月1日から始まる。あるアパートメントを舞台に、様々なアーティストやクリエーターが集い、音楽を楽しむという設定。アパートメントの住人として、BMSGアーティストのほか、「ALI」のボーカリストLEO、「Dos Monos」のトラックメイカー・MCの荘子it、ダンサー・表現者のアオイヤマダが出演する。番組は大きく音楽について深く語り合うトークコーナーと、アパートメントの一室で繰り広げる音楽ライブで構成される。</strong></p><p>**ショーケースを軸にライブの映像を配信、事務所の垣根を越えた交流を見せるダンス&amp;ボーカルのプロジェクト「D.U.N.K.」も、「新しい音楽番組」の1つの形だったが、今回は「音楽そのものの本質的な楽しさ」にフォーカスした番組になるようだ。タッグを組んだのは、BE:FIRSTを生んだオーディ</p><p>=== 文件名: PART3/8.md === ► 2024/04</p><h2 id="法人としてのbmsg、ceoとしての自分の成長を感じた日" tabindex="-1">法人としてのBMSG、CEOとしての自分の成長を感じた日 <a class="header-anchor" href="#法人としてのbmsg、ceoとしての自分の成長を感じた日" aria-label="Permalink to &quot;法人としてのBMSG、CEOとしての自分の成長を感じた日&quot;">​</a></h2><p>#リーダーシップ #マネジメント強化 #法人格の成長 #新規事業 #G&amp;G</p><h3 id="「bmsgの-勢い-を加速させるためには、-勢いがある-とたくさんの人に感じていただくことも必要」" tabindex="-1">「BMSGの“勢い”を加速させるためには、“勢いがある”とたくさんの人に感じていただくことも必要」 <a class="header-anchor" href="#「bmsgの-勢い-を加速させるためには、-勢いがある-とたくさんの人に感じていただくことも必要」" aria-label="Permalink to &quot;「BMSGの“勢い”を加速させるためには、“勢いがある”とたくさんの人に感じていただくことも必要」&quot;">​</a></h3><p><strong>2024年4月中旬、BMSGは2回目となる「Greeting &amp; Gathering&#39;24」(以下、「G&amp;G&#39;24」)を開催した。「G&amp;G」とは、BMSGが関係する各社を招待して法人としてのBMSGをプレゼンテーションするとともに、その理念やビジョンに賛同する“応援者”を増やし、親睦を深める会でもある。</strong></p><p><strong>「G&amp;G&#39;24」は、昨年よりも規模が大きくなり参加者は約400人、さらに、昨年はなかった社長であるSKY-HI自ら登壇してのプレゼンテーションが50分程度を占めたことに、マネジメント領域での発信が一層強まったように感じた。</strong></p><p>初回である昨年の開催は、コロナ禍がやや明けつつある時期。大手の事務所さんであればあるほど、まだ会社としては大人数による集まりを開催しにくいタイミングでした。逆に言えば、新興の事務所であるBMSGにとっては先駆けて催し</p><p>=== 文件名: PART3/9.md === ► 2024/05</p><h2 id="ソロ5人での「bmsg-posse」を世に出す意図は" tabindex="-1">ソロ5人での「BMSG POSSE」を世に出す意図は？ <a class="header-anchor" href="#ソロ5人での「bmsg-posse」を世に出す意図は" aria-label="Permalink to &quot;ソロ5人での「BMSG POSSE」を世に出す意図は？&quot;">​</a></h2><p>#新プロジェクト #マネジメント #リーダーシップ #遊び #BMSGPOSSE</p><h3 id="「世の中は得てして、よりビジネス的でないもの、プリミティブな欲求を直接出したもの、より遊べているものが数字につながったりもするもの」" tabindex="-1">「世の中は得てして、よりビジネス的でないもの、プリミティブな欲求を直接出したもの、より遊べているものが数字につながったりもするもの」 <a class="header-anchor" href="#「世の中は得てして、よりビジネス的でないもの、プリミティブな欲求を直接出したもの、より遊べているものが数字につながったりもするもの」" aria-label="Permalink to &quot;「世の中は得てして、よりビジネス的でないもの、プリミティブな欲求を直接出したもの、より遊べているものが数字につながったりもするもの」&quot;">​</a></h3><p><strong>BMSGに所属するソロアーティストであるSKY-HI、Novel Core、Aile The Shota、edhiii boi、REIKOの5人が「BMSG POSSE」として本格始動した。5月29日に『Girlfriend』を配信。さらに日本各地の音楽フェスへの出演を次々と決めている。当初は企画ユニットかと思われたが、SKY-HIはBMSG POSSE(以下、POSSE)を語る際に「デビュー」という言葉を使った。BMSGが放つ新グループとして、POSSEは今後どのような活動をし、BMSGにとってどのような存在となっていくのか。まずはこのタイミングで世に出す意図を聞いた。</strong></p><p>POSSEはあくまで「クルー」で、グループというわけではないですが、グループ活動とソロ活動を並行してやるケースは珍しくないですよね。そうしたと</p><p>=== 文件名: README.md === SKY-HI Management 2</p><p>=== 文件名: あとがき.md === あとがき</p><p>奇特な人生が生んだ奇特な価値観をつづった奇特な本著を読んでくださった奇特な皆様、どうもありがとうございました。</p><p>前作では会社のマネジメント、組織のマネジメントなどに焦点が当たった回がもう少し多かったかのように思いますが、今作はだいぶ音楽業界の話が多いですね。</p><p>これには2つの要因があると思います。</p><p>1つは、日本の音楽業界や芸能界が停滞していることに気がついた人が増えていること。「マネジメントのはなし。」で書かれていることの中で多少なりともある音楽業界の構造への指摘は、実は自分が20代の頃から折に触れてしてきましたが、話題にもなりませんでした(笑)。それがあるタイミングから注目を集め始め、今や炎上案件にまでなるようになりました。つまり、世の中の関心ごととして捉えていただけるところまできたということです。</p><p>そしてもう1つは、実際に芸能界が変わり始めてきたからです。そしてBMSGがその1つのきっかけであったことは、おごらずとも自覚すべきことだと思っております。</p><p>必ず音楽業界は変わります。これも起業前から言っていたのですが、「世の中が変わるか自分が死ぬか」です(笑)。</p><p>では、なんでそこまでして自分がこの音楽業</p><p>=== 文件名: 作者.md ===</p><h2 id="sky-hi" tabindex="-1">SKY-HI <a class="header-anchor" href="#sky-hi" aria-label="Permalink to &quot;SKY-HI&quot;">​</a></h2><p>1986年12月12日生まれ、千葉県出身。2005年、AAAのメンバーとしてデビューし、同時期から「SKY-HI」としても活動をスタート。SKY-HIの名前の由来には「空のように高く無限の可能性を」というメッセージを含む。</p><p>以降、ラッパー、トラックメイカー、プロデューサーとして幅広く活動。卓越したラップ&amp;ダンス&amp;ヴォーカルスキルと豊かな音楽性を備え、ジャンルの垣根を越えた他に類を見ないパフォーマンスを見せる。自らバンド音源や演出、照明に至るまでプロデュースするライブツアーは毎度完売が続出。発表する作品群も、リリシストとしての力量を遺憾なく発揮した詞、緻密に計算されたストーリーとメッセージが詰まった広い振れ幅などで評価される。</p><p>2020年には、マネジメント/レーベル「BMSG」を立ち上げ代表取締役CEOに就任。第1号アーティストとしてNovel Coreと契約したのに続き、ボーイズグループBE:FIRSTやMAZZELをプロデュース。アーティスト・プロデューサー・経営者と多岐に渡り才能を発揮している。</p><p>写真 上野裕二</p><p>ヘアメイク 椎津惠</p><p>ブックデザイン 山﨑将弘</p><h2 id="編集-横田直子-山本伸夫" tabindex="-1">編集 横田直子 山本伸夫 <a class="header-anchor" href="#編集-横田直子-山本伸夫" aria-label="Permalink to &quot;編集 横田直子 山本伸夫&quot;">​</a></h2><p>【输出任务】： 请你输出一份极致详尽的中日对照【术语与风格指南 (Style Guide)】。这份指南将作为后续所有章节翻译（Translation）、编辑（Editing）和校对（Proofreading）的最高规范指导。 必须包含：</p><ol><li>人名与专有名词对照表：包含组合成员名字、经纪公司、乐队、关联人物的统一中文译法。</li><li>核心黑话与业界术语：提取访谈中涉及的行业、音乐技术、特有梗或黑话。</li><li>文风与语气设定规范：分析提问者（如杂志记者）和受访者（如BE:FIRST各成员）的说话习惯与性格基调（例如：谁说话比较谦逊多用敬语、谁比较热血口语化、谁喜欢用外来语），并规定其中文对应的语气语调。</li></ol><p>请直接将整理好的 MarkDown 格式指南内容写入到目标文件中，不需要任何寒暄。</p>',287)])])}const B=e(i,[["render",p]]);export{b as __pageData,B as default};
